#!/usr/bin/env node
// Runs every Lambda function declared by the CDK app through `sam local
// invoke`, using fixture events/expectations under test/events/<function-id>.
// The fixture directory is named after the CDK construct id (the second-to-last
// segment of a Lambda resource's "aws:cdk:path" metadata, e.g.
// "asuyer/ApiStack/Echo/Resource" -> "Echo"). SAM can't resolve construct ids
// itself when the stack is nested inside a CDK Stage, so the function is
// invoked by its CloudFormation logical id read from the synthesized template.
//
// Generated by Claude Code on 10/23/26

import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { basename, join } from "node:path";
import { isDeepStrictEqual } from "node:util";

const CDK_OUT_DIR = "cdk.out";
const CDK_ASSEMBLY_DIR = "assembly-staging";
const EVENTS_DIR = "test/events";

// Strips // and /* */ comments and trailing commas so fixtures can be parsed
// as plain JSON. String literals are copied through untouched.
function stripJsonc(text) {
  let out = "";
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (ch === '"') {
      let j = i + 1;
      while (j < text.length && text[j] !== '"') j += text[j] === "\\" ? 2 : 1;
      out += text.slice(i, j + 1);
      i = j + 1;
    } else if (ch === "/" && text[i + 1] === "/") {
      while (i < text.length && text[i] !== "\n") i++;
    } else if (ch === "/" && text[i + 1] === "*") {
      const end = text.indexOf("*/", i + 2);
      i = end === -1 ? text.length : end + 2;
    } else {
      out += ch;
      i++;
    }
  }
  return out.replace(/,(\s*[}\]])/g, "$1");
}

function readJsonc(path) {
  return JSON.parse(stripJsonc(readFileSync(path, "utf-8")));
}

function synth() {
  console.log("Synthesizing CDK app...");
  execFileSync("npx", ["cdk", "synth", "--quiet", "--no-staging"], {
    stdio: "inherit",
  });
}

function findStackTemplates() {
  const manifest = JSON.parse(
    readFileSync(join(CDK_OUT_DIR, CDK_ASSEMBLY_DIR, "manifest.json"), "utf-8"),
  );

  return Object.values(manifest.artifacts ?? {})
    .filter((artifact) => artifact.type === "aws:cloudformation:stack")
    .map((artifact) =>
      join(CDK_OUT_DIR, CDK_ASSEMBLY_DIR, artifact.properties.templateFile),
    );
}

function findLambdaFunctions(templatePath) {
  const template = JSON.parse(readFileSync(templatePath, "utf-8"));

  return Object.entries(template.Resources ?? {})
    .filter(([, resource]) => resource.Type === "AWS::Lambda::Function")
    .map(([logicalId, resource]) => {
      const cdkPath = resource.Metadata?.["aws:cdk:path"] ?? logicalId;
      const segments = cdkPath.split("/");
      // segments: [StageName?, StackName, ...constructPath, "Resource"]
      return { logicalId, functionId: segments[segments.length - 2] };
    });
}

// Compares the whole proxy response. The body is parsed when it is JSON so
// formatting differences (whitespace, key order) don't cause failures.
function normalize(response) {
  let body = response.body;
  try {
    body = JSON.parse(body);
  } catch {
    // Not JSON (e.g. "" for 204 No Content), compare the raw string
  }
  return { ...response, body };
}

// Runs one fixture and returns { status: "pass" | "fail" | "skip", detail }.
// Never throws, so one broken case can't stop the remaining ones from running.
function runCase(logicalId, templatePath, eventFile, tmpDir) {
  const caseName = basename(eventFile, ".event.jsonc");
  const expectedFile = eventFile.replace(/\.event\.jsonc$/, ".expected.jsonc");

  if (!existsSync(expectedFile)) {
    return { status: "skip", detail: `no ${basename(expectedFile)}` };
  }

  try {
    const expected = normalize(readJsonc(expectedFile));

    // SAM only accepts plain JSON events
    const eventJson = join(tmpDir, `${caseName}.event.json`);
    writeFileSync(eventJson, JSON.stringify(readJsonc(eventFile)));

    const stdout = execFileSync(
      "sam",
      ["local", "invoke", logicalId, "-t", templatePath, "-e", eventJson],
      { stdio: ["ignore", "pipe", "inherit"] },
    ).toString();
    const actual = normalize(JSON.parse(stdout));

    if (isDeepStrictEqual(actual, expected)) {
      return { status: "pass" };
    }
    return {
      status: "fail",
      detail:
        `expected: ${JSON.stringify(expected)}\n` +
        `actual:   ${JSON.stringify(actual)}`,
    };
  } catch (error) {
    return { status: "fail", detail: error.message.split("\n")[0] };
  }
}

function printDetail(detail) {
  for (const line of detail.split("\n")) console.log(`      ${line}`);
}

function main() {
  synth();

  const tmpDir = mkdtempSync(join(tmpdir(), "test-sam-"));
  const results = [];

  try {
    for (const templatePath of findStackTemplates()) {
      for (const { logicalId, functionId } of findLambdaFunctions(
        templatePath,
      )) {
        const eventDir = join(EVENTS_DIR, functionId);
        if (!existsSync(eventDir)) {
          console.log(`${functionId}: no fixtures in ${eventDir}/, skipping`);
          continue;
        }

        console.log(`${functionId} (${logicalId}):`);
        const eventFiles = readdirSync(eventDir)
          .filter((file) => file.endsWith(".event.jsonc"))
          .map((file) => join(eventDir, file));

        for (const eventFile of eventFiles) {
          const name = `${functionId}/${basename(eventFile, ".event.jsonc")}`;
          const result = runCase(logicalId, templatePath, eventFile, tmpDir);
          results.push({ name, ...result });

          console.log(`  ${result.status.toUpperCase()} ${name}`);
          if (result.detail) printDetail(result.detail);
        }
      }
    }
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }

  if (results.length === 0) {
    console.log("No sam test fixtures found.");
    return;
  }

  const byStatus = (status) => results.filter((r) => r.status === status);
  const passed = byStatus("pass");
  const failed = byStatus("fail");
  const skipped = byStatus("skip");

  console.log("\n=== sam local invoke summary ===");
  if (passed.length > 0) {
    console.log(`\nPassed (${passed.length}):`);
    for (const { name } of passed) console.log(`  PASS ${name}`);
  }
  if (skipped.length > 0) {
    console.log(`\nSkipped (${skipped.length}):`);
    for (const { name, detail } of skipped) {
      console.log(`  SKIP ${name} (${detail})`);
    }
  }
  if (failed.length > 0) {
    console.log(`\nFailed (${failed.length}):`);
    for (const { name, detail } of failed) {
      console.log(`  FAIL ${name}`);
      printDetail(detail);
    }
  }

  console.log(
    `\n${passed.length} passed, ${failed.length} failed, ` +
      `${skipped.length} skipped, ${results.length} total`,
  );
  if (failed.length > 0) process.exit(1);
}

main();
